def run(workspace, content_bytes, fault=None):
    if content_bytes == b'':
        return ('ok', b'')

    # Create staging file with default permissions
    identity = workspace.create(workspace.default_readers, content_bytes)

    # Handle fault scenarios
    if fault == 'create':
        workspace.remove(identity)
        return ('error', 'staging unavailable')

    # Simulate writing to the file (in real scenario this would happen automatically)
    if fault == 'write':
        workspace.remove(identity)
        return ('error', 'staging unavailable')

    # Simulate handoff to consumer (this is where we'd normally do the actual handoff)
    if fault == 'handoff':
        workspace.remove(identity)
        return ('error', 'staging unavailable')

    # Normal case - return the content as expected
    result_content = workspace.read(identity, 'consumer')
    workspace.remove(identity)

    if result_content is None:
        return ('error', 'staging unavailable')

    return ('ok', content_bytes)
EOF

